const meta = {
  component: Carousel,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Built with Embla, the carousel supports animated transitions and swipe gestures.

**Import:** `@/registry/erbium/ui/carousel`

## About

The carousel component is built using the [Embla Carousel](https://www.embla-carousel.com/) library.

## Usage

```tsx
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
} from "@/registry/erbium/ui/carousel";
```

```tsx
<Carousel>
  <CarouselContent>
    <CarouselItem>...</CarouselItem>
    <CarouselItem>...</CarouselItem>
    <CarouselItem>...</CarouselItem>
  </CarouselContent>
  <CarouselPrevious />
  <CarouselNext />
</Carousel>
```

## Composition

Use the following composition to build a `Carousel`:

```text
Carousel
├── CarouselContent
│   ├── CarouselItem
│   └── CarouselItem
├── CarouselPrevious
└── CarouselNext
```

## Options

You can pass options to the carousel using the `opts` prop. See the [Embla Carousel docs](https://www.embla-carousel.com/api/options/) for more information.

```tsx
<Carousel
  opts={{
    align: "start",
    loop: true,
  }}
>
  <CarouselContent>
    <CarouselItem>...</CarouselItem>
    <CarouselItem>...</CarouselItem>
    <CarouselItem>...</CarouselItem>
  </CarouselContent>
</Carousel>
```

## External documentation

Embla Carousel supplies the carousel behavior and React hook. The autoplay example uses its Autoplay plugin.

- [Embla Carousel React (v8)](https://www.embla-carousel.com/docs/v8/get-started/react)
- [Embla Carousel Autoplay (v8)](https://www.embla-carousel.com/docs/v8/plugins/autoplay)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Carousel>;

export default { ...meta, title: "Components/Carousel",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

